                        valid = False
            if valid:
                patterns[source] = (target,
                    [[grid[r+y][c+3+x] == target for x in range(3)] for y in range(3)])

    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            source = grid[r][c]
