            out[r-top][c-left] = bg
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if (top < yy < bottom and left < xx < right
                            and grid[yy][xx] == source
                            and out[yy-top][xx-left] == source):
